void __thiscall
CHARACTER::AttackedByFire(CHARACTER *this,LPCHARACTER pkAttacker,int amount,int count)

{
  DWORD dwInfoID;
  LPEVENT pEVar1;
  TFireEventInfo *info;
  
                    /* Unresolved local var: DWORD dwEI@[DW_OP_reg0(EAX)] */
  if (this->m_pkFireEvent == (LPEVENT)0x0) {
    AddAffect(this,0xd8,'\0',0,0x1d,count * 3 + 1,0,true,false);
    dwInfoID = __AllocEventInfo(0x10,&info);
    info->count = count;
    info->amount = amount;
    info->ch = this;
    info->attacker_pid = pkAttacker->m_dwPlayerID;
    pEVar1 = event_create_ex(fire_event,dwInfoID,1,"char_resist.cpp",0x8f);
    this->m_pkFireEvent = pEVar1;
  }
  return;
}
